from solution import freq_count


def test_issue_example_from_description():
    """Get the frequency of the elements in a list."""
    assert freq_count([10, 10, 10, 10, 20, 20, 20, 20, 40, 40, 50, 50, 30]) == ({10: 4, 20: 4, 40: 2, 50: 2, 30: 1})  # 4=1+1+1+1, 2=1+1, 1=1


def test_issue_empty_list():
    """Get the frequency of the elements in a list with empty input."""
    assert freq_count([]) == ({})  # 0 elements so 0+0=0 counts


def test_issue_single_element():
    """Get the frequency of the elements in a single-element list."""
    assert freq_count([99]) == ({99: 1})  # 1=1 one occurrence


def test_issue_all_identical():
    """Get the frequency when all elements are identical."""
    assert freq_count([5, 5, 5, 5, 5]) == ({5: 5})  # 5=1+1+1+1+1


def test_issue_all_distinct():
    """Get the frequency when every element occurs once."""
    assert freq_count([1, 2, 3, 4]) == ({1: 1, 2: 1, 3: 1, 4: 1})  # 1=1 each once, 1+1+1+1=4 total


def test_issue_interleaved_repeats():
    """Get the frequency of interleaved repeated elements."""
    assert freq_count([1, 2, 1, 2, 1]) == ({1: 3, 2: 2})  # 3=1+1+1, 2=1+1, total 3+2=5


def test_issue_string_elements():
    """Get the frequency of the elements in a list of strings."""
    assert freq_count(["a", "b", "a", "c", "b", "a"]) == ({"a": 3, "b": 2, "c": 1})  # 3=1+1+1, 2=1+1, 1=1


def test_issue_negative_and_zero():
    """Get the frequency with negative numbers and zero."""
    assert freq_count([-1, 0, -1, 0, 0]) == ({-1: 2, 0: 3})  # 2=1+1, 3=1+1+1, total 2+3=5


def test_contract_returns_dict_mapping():
    """Result must be a dict mapping each element to its frequency."""
    assert freq_count([10, 20, 10]) == ({10: 2, 20: 1})  # 2=1+1, 1=1, total 2+1=3


def test_contract_counts_sum_to_length():
    """Frequencies must sum to the input length."""
    assert freq_count([4, 4, 4, 5, 5, 6]) == ({4: 3, 5: 2, 6: 1})  # 3=1+1+1, 2=1+1, 1=1, total 3+2+1=6


def test_contract_two_occurrences_each():
    """Each distinct element maps to its exact count."""
    assert freq_count([7, 8, 9, 7, 8, 9]) == ({7: 2, 8: 2, 9: 2})  # 2=1+1 each, total 2+2+2=6
